This hook subscribes to external browser APIs (`visualViewport` resize and scroll events) via `useEffect` and mirrors the external value directly into state with `setViewportOffsetTop(targetOffsetTop)`. This is the exact pattern that `useSyncExternalStore` was designed to replace — it handles concurrent rendering edge cases (tearing) and avoids the extra render pass of `useEffect` + `setState`.

Replace the `useState` + `useEffect` subscription with `useSyncExternalStore`:

```tsx
import {useCallback, useSyncExternalStore} from 'react';
import addViewportResizeListener from '@libs/VisualViewport';

export default function useViewportOffsetTop(): number {
    const subscribe = useCallback((callback: () => void) => {
        const unsubscribe = addViewportResizeListener(callback);
        window.visualViewport?.addEventListener('scroll', callback);
        return () => {
            window.visualViewport?.removeEventListener('scroll', callback);
            unsubscribe();
        };
    }, []);

    return useSyncExternalStore(
        subscribe,
        () => window.visualViewport?.offsetTop ?? 0,
        () => 0,
    );
}
```

